\pset pager off
SELECT now() AT TIME ZONE 'Europe/Moscow' AS now_msk;
SELECT kind,status,start_date,end_date,next_campaign_offset,jsonb_array_length(COALESCE(pair_ids_json,'[]'::jsonb)) AS pair_count,next_attempt_at_utc AT TIME ZONE 'Europe/Moscow' AS next_msk,error_code,wait_reason FROM wb_sync_jobs WHERE store_id='218f4679-4dc1-4543-b0e7-426e6f11d080' AND kind='clusters' ORDER BY created_at_utc DESC LIMIT 14;
SELECT "Source","State",min("StartDate"),max("EndDate"),count(*),max("LastAttemptAtUtc") AT TIME ZONE 'Europe/Moscow' AS attempted_msk FROM wb_source_quality WHERE "StoreId"='218f4679-4dc1-4543-b0e7-426e6f11d080' AND "Source"='clusters' AND "StartDate"<='2026-10-18' AND "EndDate">='2026-10-12' GROUP BY 1,2;
SELECT c.id,c.wb_campaign_id,c.name,c.wb_status,count(DISTINCT d.date) AS article_days,count(*) AS article_rows FROM campaigns c JOIN campaign_nomenclature_statistics d ON d.campaign_id=c.id WHERE c.store_id='218f4679-4dc1-4543-b0e7-426e6f11d080' AND d.date>='2026-10-12' AND d.date<'2026-10-19' GROUP BY c.id ORDER BY c.wb_status,c.wb_campaign_id;
SELECT c.wb_campaign_id,q."State",count(*),max(q."LastAttemptAtUtc") AT TIME ZONE 'Europe/Moscow' AS attempted_msk FROM wb_source_quality q JOIN campaigns c ON c.id::text=split_part(q."Entity",':',1) WHERE q."StoreId"='218f4679-4dc1-4543-b0e7-426e6f11d080' AND q."Source"='clusters' AND q."StartDate">='2026-10-12' AND q."EndDate"<='2026-10-18' GROUP BY 1,2 ORDER BY 1,2;
SELECT "Id","Kind","State","RequestedAtUtc" AT TIME ZONE 'Europe/Moscow' AS requested_msk,"HttpStatus",length("Body") FROM wb_response_snapshots WHERE "StoreId"='218f4679-4dc1-4543-b0e7-426e6f11d080' AND "Kind"='clusters' ORDER BY "RequestedAtUtc" DESC LIMIT 8;
